// Site is served from the domain root (ftubt41.web.id), so no base path prefix is needed.
// Set NEXT_PUBLIC_BASE_PATH only if the site is ever hosted under a sub-path again.
const basePath = process.env.NEXT_PUBLIC_BASE_PATH ?? "";

export const getAsset = (path: string) => {
  if (!path) return "";
  if (path.startsWith("http") || path.startsWith("data:")) return path;
  if (basePath && path.startsWith(basePath + "/")) return path;
  return `${basePath}${path.startsWith("/") ? "" : "/"}${path}`;
};

// Card-sized graduate photo generated by scripts/optimize_images.py.
// Full-size photos stay in /graduates for the modal, profile page and story export.
export const getThumb = (path: string) => {
  if (!path || !path.startsWith("/graduates/") || path.startsWith("/graduates/thumbs/")) return getAsset(path);
  const file = path.slice("/graduates/".length).replace(/\.[^./]+$/, ".webp");
  return getAsset(`/graduates/thumbs/${file}`);
};

// onError handler: if a thumbnail is missing, fall back to the full-size photo once.
export const fallbackToFull = (path: string) => (e: { currentTarget: HTMLImageElement }) => {
  const full = getAsset(path);
  if (!e.currentTarget.src.endsWith(full)) e.currentTarget.src = full;
};
